UPDATE t_inventory
SET stock = stock - #{quantity}, version = version + 1
WHERE book_id = #{bookId} AND stock >= #{quantity} AND version = #{version}

UPDATE t_inventory
SET stock = stock + #{quantity}
WHERE book_id = #{bookId}

UPDATE t_inventory
SET stock = stock - #{quantity}, locked_stock = locked_stock + #{quantity}, version = version + 1
WHERE book_id = #{bookId} AND stock >= #{quantity} AND version = #{version}

UPDATE t_inventory
SET locked_stock = locked_stock - #{quantity}
WHERE book_id = #{bookId} AND locked_stock >= #{quantity}

UPDATE t_inventory
SET stock = stock + #{quantity}, locked_stock = locked_stock - #{quantity}
WHERE book_id = #{bookId} AND locked_stock >= #{quantity}
